<script lang="ts">import {page}from '$app/state';import {getPipelineDefinition,listPipelineRuns,pipelineErrorMessage,runPipeline,type NexetlError,type PipelineDefinition,type PipelineRun}from '$lib/api/pipelines';import {formatTimestamp}from '$lib/format';import PipelineWorkspaceNav from '$lib/components/PipelineWorkspaceNav.svelte';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Button from '$lib/components/ui/Button.svelte';import Alert from '$lib/components/ui/Alert.svelte';import StatusBadge from '$lib/components/ui/StatusBadge.svelte';let pipeline=$state<PipelineDefinition|null>(null),runs=$state<PipelineRun[]>([]),loading=$state(true),pending=$state(false),error=$state('');$effect(()=>{if(page.params.pipelineDefinitionId)void load(page.params.pipelineDefinitionId)});async function load(id:string){try{[pipeline,{items:runs}]=await Promise.all([getPipelineDefinition(id),listPipelineRuns(id)])}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{loading=false}}async function start(){if(!pipeline)return;pending=true;try{const run=await runPipeline(pipeline.id);location.href=`/pipelines/${pipeline.id}/runs/${run.id}`}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}</script>
<svelte:head><title>Run History | NEXETL</title></svelte:head>{#if pipeline}<PageHeader title={pipeline.name} description="Run history, triggers, durations and outcomes."><Button loading={pending} disabled={pipeline.state==='ARCHIVED'} onclick={start}>Run pipeline</Button></PageHeader><PipelineWorkspaceNav pipelineId={pipeline.id}/>{/if}{#if error}<Alert variant="error">{error}</Alert>{/if}{#if loading}<p role="status">Loading Runs…</p>{:else if runs.length}<div class="table"><table><thead><tr><th>Status</th><th>Version</th><th>Trigger</th><th>Queued</th><th>Duration</th><th>Rows</th></tr></thead><tbody>{#each runs as run}<tr><td><a href={`/pipelines/${run.pipelineId}/runs/${run.id}`}><StatusBadge state={run.status}/></a></td><td>v{run.version}</td><td>{run.triggerType}</td><td>{formatTimestamp(run.queuedAt)}</td><td>{run.durationMs===null?'—':`${run.durationMs} ms`}</td><td>{run.metrics.rowsWritten??'—'}</td></tr>{/each}</tbody></table></div>{:else}<section class="empty"><h2>No Runs yet</h2><p>Validate and run this Pipeline to create its first immutable execution record.</p></section>{/if}
<style>.table{overflow:auto;border:1px solid var(--border-default);border-radius:var(--radius-lg);background:#fff}table{width:100%;border-collapse:collapse;font-size:.72rem}th,td{padding:.7rem .8rem;border-bottom:1px solid var(--border-subtle);text-align:left}th{background:var(--bg-subtle);color:var(--text-muted);font-size:.6rem;text-transform:uppercase}.empty{border:1px dashed var(--border-strong);border-radius:var(--radius-lg);padding:2rem;text-align:center}.empty h2{font-size:1rem}.empty p{color:var(--text-muted);font-size:.75rem}</style>
